from pathlib import Path
import markdown
ROOT=Path(__file__).resolve().parents[1]
body=markdown.markdown((ROOT/'docs/MANUAL-WINDOWS-TESTS.md').read_text(encoding='utf-8'),extensions=['tables','fenced_code'])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Naqla 0.8 · Windows testing</title><style>*{box-sizing:border-box}body{margin:0;background:#121820;color:#f5f0e6;font:15px/1.8 'Segoe UI',Tahoma,sans-serif}main{max-width:1100px;margin:auto;padding:28px}h1,h2,h3{color:#ffc35a}h1{font-size:27px}h2{margin-top:32px}a{color:#ffc35a}code{color:#8ed8c3;overflow-wrap:anywhere}pre{overflow:auto;background:#1c2530;padding:15px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border:1px solid #344454;padding:10px;text-align:left;vertical-align:top}th{background:#263443}tbody tr:nth-child(2n){background:#17212b}p,li{overflow-wrap:anywhere}.ar{direction:rtl;text-align:right;border:1px solid #705d3d;padding:16px;background:#1c2530}strong{color:#fff0cd}@media(max-width:600px){main{padding:14px}table{display:block;overflow-x:auto}td{min-width:160px}}</style><main><div class="ar"><strong>دليل الاختبار الحالي · نقلة 0.8</strong><p>اسحب الملف واضغط Shift، ثم Ctrl للأدوات. حرّر Shift قبل Tab للتالي؛ Shift+Tab للسابق. الأصول محفوظة، وSmart Rename يحتاج تأكيداً لتغيير الأسماء فعلياً. اختبارات السحب الحقيقية والشاشات والتثبيت النظيف ما زالت يدوية.</p><a href="../preview/context-editors.html">مراجعة المحررات</a> · <a href="END-TO-END-TEST-REPORT.md">تقرير النتائج</a></div>BODY</main></html>'''.replace('BODY',body)
(ROOT/'docs/TESTING.html').write_text(page,encoding='utf-8')
print('Rendered current manual checklist as standalone HTML.')
